// Хайповые курсы: алгоритмы, ИИ-2, кибербезопасность, бренд, маркетплейсы,
// маркетинг, переговоры, фриланс, учёба, психология денег, дизайн и видео.

const C = (t, b) => ({ t, b });
const Q = (q, options, correct, explain) => ({ type: 'single', q, options, correct, explain });
const B = (q, correct, explain) => ({ type: 'bool', q, options: ['Верно', 'Неверно'], correct, explain });
const L = (id, title, cards, quiz, extra = {}) => ({ id, title, xp: 15, cards, quiz, ...extra });

function artFor(c1, c2, i) {
  const v = i % 4;
  const inner = [
    `<circle cx="100" cy="72" r="34" fill="#ffc800"/><circle cx="100" cy="72" r="24" fill="none" stroke="#fff" stroke-opacity=".6" stroke-width="3"/><text x="100" y="84" text-anchor="middle" font-size="30" font-weight="900" fill="#a86e00" font-family="Nunito,sans-serif">₽</text>`,
    `<rect x="52" y="86" width="18" height="30" rx="5" fill="#fff" opacity=".85"/><rect x="82" y="70" width="18" height="46" rx="5" fill="#fff"/><rect x="112" y="52" width="18" height="64" rx="5" fill="#ffc800"/><path d="M50 62 L84 46 L104 54 L136 34" fill="none" stroke="#fff" stroke-width="5" stroke-linecap="round"/><path d="M126 32 h12 v12" fill="none" stroke="#fff" stroke-width="5" stroke-linecap="round"/>`,
    `<path d="M100 30 L109 54 L135 55 L115 71 L121 96 L100 82 L79 96 L85 71 L65 55 L91 54 Z" fill="#ffc800"/><circle cx="52" cy="44" r="6" fill="#fff" opacity=".8"/><circle cx="152" cy="96" r="7" fill="#fff" opacity=".6"/>`,
    `<rect x="42" y="42" width="72" height="44" rx="14" fill="#fff"/><path d="M58 86 l0 16 l18 -16z" fill="#fff"/><rect x="92" y="66" width="66" height="40" rx="13" fill="#ffc800"/><path d="M142 106 l0 14 l-16 -14z" fill="#ffc800"/><circle cx="62" cy="64" r="5" fill="${c1}"/><circle cx="80" cy="64" r="5" fill="${c1}" opacity=".6"/><circle cx="98" cy="64" r="5" fill="${c1}" opacity=".35"/>`,
  ][v];
  return `<svg viewBox="0 0 200 150" xmlns="http://www.w3.org/2000/svg"><rect width="200" height="150" rx="18" fill="${c1}"/><circle cx="168" cy="24" r="46" fill="${c2}" opacity=".55"/><circle cx="26" cy="132" r="34" fill="${c2}" opacity=".4"/>${inner}</svg>`;
}
function mkCourse(o) {
  o.units.forEach((u) => { u.color = o.color; u.dark = o.dark; });
  o.units.flatMap((u) => u.lessons).forEach((l, i) => { l.art = artFor(o.color, o.dark, i); });
  o.art = artFor(o.color, o.dark, 1);
  return o;
}

